tool_input.command:
cat > dlt_pipeline.json << 'EOF'
{
  "name": "${MLPAB_DATABRICKS_PREFIX}_filter_events",
  "storage": "/pipelines/${MLPAB_DATABRICKS_PREFIX}_filter_events",
  "configuration": {
    "pipelines.trigger.interval": "24 hours",
    "pipelines.clusterShutdown.delay": "10 minutes"
  },
  "clusters": [
    {
      "label": "default",
      "num_workers": 1,
      "node_type_id": "i3.xlarge",
      "spark_conf": {
        "spark.databricks.delta.optimizeWrite.enabled": "true",
        "spark.databricks.delta.autoCompact.enabled": "true"
      }
    }
  ],
  "libraries": [
    {
      "notebook": {
        "path": "/Repos/${MLPAB_DATABRICKS_USER}/${MLPAB_DATABRICKS_PREFIX}/filter_events.py"
      }
    }
  ],
  "target": "${MLPAB_DATABRICKS_SCHEMA}",
  "continuous": false,
  "development": true,
  "photon": false,
  "edition": "ADVANCED"
}
EOF

